(()=>{'use strict';
/* UI 设计原型：所有记录为虚构数据，所有权限仅模拟，不用于生产。 */
const A = { pages: {}, actions: {}, inputs: {}, ui: {}, STORAGE: 'stackoryn-design-v02' };
A.uid = prefix => prefix + '-' + Date.now().toString(36) + Math.random().toString(36).slice(2,6);
A.names = ['陈以宁','林予安','王知远','张可欣','周一航','李沐晴','赵书言','许亦辰'];
A.now = '2026-11-08T14:32:00+08:00';
A.initial = () => ({ schemaVersion: 2, edition: 'community',
  sources: [
    { id:'orders',name:'订单生产库',engine:'PostgreSQL',environment:'生产',host:'orders.internal.example',port:'5432',database:'commerce',state:'connected',tables:['orders','payments'],domain:'orders',ssl:true,updated:'14:32' },
    { id:'members',name:'会员中心',engine:'MySQL',environment:'生产',host:'members.internal.example',port:'3306',database:'crm',state:'connected',tables:['customers','subscriptions'],domain:'members',ssl:true,updated:'14:32' },
    { id:'events',name:'行为分析仓',engine:'ClickHouse',environment:'分析',host:'analytics.internal.example',port:'8443',database:'analytics',state:'connected',tables:['user_events'],domain:'events',ssl:true,updated:'14:32' },
    { id:'orders-test',name:'订单测试库',engine:'PostgreSQL',environment:'测试',host:'127.0.0.1',port:'5432',database:'commerce_test',state:'offline',tables:['orders','payments'],domain:'orders',ssl:false,updated:'昨天 17:20' }
  ],
  workspaces: [
    {id:'customer-360',title:'客户业务总览',description:'把客户资料、订单和使用情况放在同一个工作台。',kind:'customer',datasourceIds:['orders','members','events'],bindings:{orders:'orders',profile:'members',activity:'events'},version:3,config:{showActivity:true,showPhone:true,showCost:true,defaultDays:'30'},updated:'2026-11-08T14:30:00+08:00'},
    {id:'order-exceptions',title:'异常订单排查',description:'定位已支付但未履约的订单，快速核查异常原因。',kind:'orders',datasourceIds:['orders'],bindings:{orders:'orders'},version:2,config:{showActivity:false,showPhone:true,showCost:true,defaultDays:'7'},updated:'2026-11-07T10:20:00+08:00'},
    {id:'members-view',title:'高价值客户检索',description:'查看会员资料与订阅状态，快速找到需要跟进的客户。',kind:'members',datasourceIds:['members'],bindings:{profile:'members'},version:1,config:{showActivity:false,showPhone:true,showCost:false,defaultDays:'30'},updated:'2026-11-06T09:40:00+08:00'}
  ],
  policies: {
    support:{label:'客服',description:'只查看自己负责的订单',fields:{phone:'masked',cost:'hidden',email:'masked'},rowScope:'assigned',export:false,aiSensitive:false,allowedSources:['orders','members','events','orders-test']},
    finance:{label:'财务',description:'查看公司范围内的财务数据',fields:{phone:'hidden',cost:'raw',email:'hidden'},rowScope:'all',export:true,aiSensitive:false,allowedSources:['orders','members','events','orders-test']},
    operator:{label:'门店运营',description:'仅查看杭州门店的数据',fields:{phone:'masked',cost:'hidden',email:'masked'},rowScope:'store',export:false,aiSensitive:false,allowedSources:['orders','members','orders-test']}
  }, drafts:{}
});
A.readState = () => { try {const s=JSON.parse(localStorage.getItem(A.STORAGE)); if(s?.schemaVersion===2&&Array.isArray(s.sources)&&Array.isArray(s.workspaces)&&s.policies)return s;}catch{} return A.initial(); };
A.state = A.readState();
A.save = () => { try {localStorage.setItem(A.STORAGE,JSON.stringify(A.state));}catch {A.ui.storageBlocked=true;} };
A.makeOrders = sourceId => Array.from({length:48},(_,i)=>({
  id:(sourceId==='orders'?'ORD':sourceId==='orders-test'?'TEST':'DEMO-'+sourceId.slice(-4).toUpperCase())+'-261108-'+(1048-i), customerId:'CUS-'+(1001+i%8),customer:A.names[i%8],
  email:['yining.chen','yuan.lin','zhiyuan.wang','kexin.zhang','yihang.zhou','muqing.li','shuyan.zhao','yichen.xu'][i%8]+'@example.com',
  phone:'138'+String(20105678+i%8).padStart(8,'0'),amount:[899,129,249,1299,499,199,2499,59][i%8],cost:[420,60,95,680,230,90,1100,20][i%8],
  channel:['微信支付','支付宝','Stripe'][i%3],status:['履约超时','履约失败','状态不一致','已完成'][i%4],
  createdAt:new Date(Date.parse(A.now)-i*5*3600000).toISOString(),store:i%2?'上海门店':'杭州门店',assignee:i%3===0?'support-01':'support-02',product:['专业版年费','团队版月费','API 用量包'][i%3]
}));
A.makeMembers = sourceId => A.names.map((name,i)=>({id:'CUS-'+(1001+i),name,email:['yining.chen','yuan.lin','zhiyuan.wang','kexin.zhang','yihang.zhou','muqing.li','shuyan.zhao','yichen.xu'][i]+'@example.com',phone:'138'+String(20105678+i),plan:i%3===0?'团队版':'专业版',store:i%2?'上海门店':'杭州门店',assignee:i%3===0?'support-01':'support-02',registered:'2026-08-'+String(10+i).padStart(2,'0'),sourceId}));
A.mask = (value,field) => field==='cost'?'••••':field==='phone'?String(value).replace(/^(\d{3})\d{4}(\d{4})$/,'$1****$2'):String(value).replace(/^(.).+(@.+)$/,'$1***$2');
A.currentPolicy = () => A.state.edition==='team'&&A.ui.role&&A.ui.role!=='owner'?A.state.policies[A.ui.role]:null;
A.source = id => A.state.sources.find(s=>s.id===id);
A.workspace = () => A.state.workspaces.find(w=>w.id===A.ui.workspaceId)||A.state.workspaces[0];
A.sourceAccess = id => {const s=A.source(id),p=A.currentPolicy();if(!s)return {ok:false,kind:'missing',title:'尚未绑定数据源',description:'在编辑器中为这个模块选择一个兼容的数据源。'};if(p&&!p.allowedSources.includes(id))return {ok:false,kind:'denied',title:'没有数据源访问权限',description:'当前演示角色未获准使用此来源，其他已授权模块不受影响。'};if(s.state==='offline')return {ok:false,kind:'offline',title:'数据源暂时不可用',description:'模拟连接已断开。恢复此数据源后即可重新读取。'};return {ok:true,source:s};};
A.rowAllowed = (row,p) => !p||p.rowScope==='all'||(p.rowScope==='store'&&row.store==='杭州门店')||(p.rowScope==='assigned'&&row.assignee==='support-01');
A.redact = row => {const p=A.currentPolicy();const result={...row};if(p)for(const [field,mode] of Object.entries(p.fields)){if(mode==='hidden')delete result[field];else if(mode==='masked'&&result[field]!=null)result[field]=A.mask(result[field],field);}return result;};
A.queryOrders = (ws,filters={}) => { const access=A.sourceAccess(ws.bindings.orders);if(!access.ok)return {...access,rows:[]};if(!access.source.tables.includes('orders'))return {ok:false,kind:'denied',title:'订单表未获授权',description:'此连接的可用表不包含 orders。请由管理员调整授权范围。',rows:[]};const policy=A.currentPolicy();let rows=A.makeOrders(ws.bindings.orders).filter(r=>A.rowAllowed(r,policy));if(ws.kind==='orders')rows=rows.filter(r=>r.status!=='已完成');if(filters.customer&&filters.customer!=='all')rows=rows.filter(r=>r.customerId===filters.customer);if(filters.days&&filters.days!=='all')rows=rows.filter(r=>Date.parse(r.createdAt)>=Date.parse(A.now)-Number(filters.days)*86400000);if(filters.channel&&filters.channel!=='all')rows=rows.filter(r=>r.channel===filters.channel);rows=rows.map(A.redact);if(filters.search){const q=filters.search.toLowerCase();rows=rows.filter(r=>[r.id,r.customer,r.email||''].some(v=>v.toLowerCase().includes(q)));}if(filters.sort==='amount')rows.sort((a,b)=>b.amount-a.amount);return {...access,rows};};
A.queryMembers = ws => {const access=A.sourceAccess(ws.bindings.profile);if(!access.ok)return {...access,rows:[]};if(!access.source.tables.includes('customers'))return {ok:false,kind:'denied',title:'客户表未获授权',description:'此连接的可用表不包含 customers。',rows:[]};const p=A.currentPolicy();return {...access,rows:A.makeMembers(ws.bindings.profile).filter(r=>A.rowAllowed(r,p)).map(A.redact)};};
A.queryActivity = (ws,customer) => {const access=A.sourceAccess(ws.bindings.activity);if(!access.ok)return {...access,values:[]};if(!access.source.tables.includes('user_events'))return {ok:false,kind:'denied',title:'行为表未获授权',description:'此连接的可用表不包含 user_events。',values:[]};const p=A.currentPolicy();if(customer&&customer!=='all'){const person=A.makeMembers('members').find(m=>m.id===customer);if(!person||!A.rowAllowed(person,p))return {ok:false,kind:'denied',title:'无权查看该客户',description:'客户记录范围同样适用于使用数据。',values:[]};}return {...access,values:[18,32,26,40,30,57,44,66,52,70,60,83].map(v=>customer&&customer!=='all'?Math.round(v*.63):v),activeCount:customer&&customer!=='all'?1:A.makeMembers('members').filter(r=>A.rowAllowed(r,p)).length};};
A.ensureUI = () => {A.ui={role:'owner',page:1,search:'',channel:'all',days:'30',customer:'all',sort:'date',workspaceId:'customer-360',modal:null,sourceSearch:'',engineFilter:'all',sourceTab:'overview',memberSearch:'',scopeTab:'fields',permissionRole:'support',...A.ui};};A.ensureUI();
A.bindingDomain={orders:'orders',profile:'members',activity:'events'};
A.bindingLabel={orders:'订单明细',profile:'客户资料',activity:'使用趋势'};
A.normalizeWorkspace = ws => {const copy=structuredClone(ws);copy.datasourceIds=[...new Set(Object.values(copy.bindings).filter(Boolean))];return copy;};
A.validBinding = (key,id) => !id||A.source(id)?.domain===A.bindingDomain[key];
A.canExport = () => !A.currentPolicy()||A.currentPolicy().export;
A.escape = val => String(val??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
A.e=A.escape;
A.money = n => new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY',maximumFractionDigits:2}).format(n);
A.date = d => new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date(d));

A.icons = {
 home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v2"/>',table:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M3 14h18M8 4v16"/>',chart:'<path d="M4 3v18h17M8 16v-5M13 16V6M18 16v-8"/>',settings:'<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="10" cy="18" r="2" fill="currentColor"/>',refresh:'<path d="M20 10a8 8 0 0 0-14-5L3 8m0-5v5h5M4 14a8 8 0 0 0 14 5l3-3m-5 0h5v5"/>',spark:'<path d="m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',warning:'<path d="m12 3 10 18H2zM12 9v5M12 17v1"/>',link:'<path d="m9 15 6-6m-4-3 2-2a5 5 0 0 1 7 7l-2 2M13 18l-2 2a5 5 0 0 1-7-7l2-2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',more:'<circle cx="5" cy="12" r="1" fill="currentColor"/><circle cx="12" cy="12" r="1" fill="currentColor"/><circle cx="19" cy="12" r="1" fill="currentColor"/>',code:'<path d="m8 5-6 7 6 7M16 5l6 7-6 7M14 3l-4 18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7"/><circle cx="12" cy="12" r="3"/>',server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M11 6.5h6M11 17.5h6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6zM13 6l5 5"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',folder:'<path d="M3 7V4h7l3 3h8v13H3z"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18M17 12h4v5h-4a2.5 2.5 0 0 1 0-5"/>',collapse:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16"/>',logout:'<path d="M9 3H3v18h6M13 8l5 4-5 4M8 12h13"/>',cloud:'<path d="M7 19a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5.5 5.5 0 0 1-1 11z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>'
};
A.icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${A.icons[name]||A.icons.grid}</svg>`;
A.btn=(text,action,extra='',variant='secondary',icon='')=>`<button type="button" class="btn ${variant}" data-action="${action}" ${extra}>${icon?A.icon(icon):''}${text}</button>`;
A.badge=(text,tone='neutral')=>`<span class="badge ${tone}">${text}</span>`;
A.engineIcon = engine => `<span class="engine-icon ${engine==='PostgreSQL'?'pg':engine==='MySQL'?'my':'ck'}">${engine==='PostgreSQL'?'P':engine==='MySQL'?'M':'C'}</span>`;
A.sourceChip=id=>{const s=A.source(id);return s?`<button class="source-chip" data-action="source-detail" data-id="${A.e(id)}">${A.engineIcon(s.engine)}<span>${A.e(s.name)}</span><span class="dot ${s.state==='offline'?'red':''}"></span></button>`:A.badge('未绑定','warning');};
A.status=state=>A.badge(`<span class="dot ${state==='offline'?'red':''}"></span>${state==='connected'?'连接可用':'连接离线'}`,state==='connected'?'success':'danger');
A.field=(label,input,hint='')=>`<label class="field"><span>${label}</span>${input}${hint?`<small>${hint}</small>`:''}</label>`;
A.input=(id,value,placeholder='',attrs='')=>`<input id="${id}" data-model="${id}" value="${A.e(value)}" placeholder="${A.e(placeholder)}" ${attrs}>`;
A.select=(id,value,options,attrs='')=>`<select id="${id}" data-model="${id}" ${attrs}>${options.map(([v,t])=>`<option value="${A.e(v)}" ${value===v?'selected':''}>${A.e(t)}</option>`).join('')}</select>`;
A.notice=(text,kind='subtle',icon='info')=>`<div class="notice ${kind}">${A.icon(icon)}<div>${text}</div></div>`;
A.empty=(title,desc,icon='database',action='')=>`<div class="empty-state">${A.icon(icon,28)}<h3>${title}</h3><p>${desc}</p>${action}</div>`;
A.pageHead=(eyebrow,title,description,actions='')=>`<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;
A.sourceFailure=(access,id)=>A.empty(access.title,access.description,access.kind==='denied'?'lock':'database',access.kind==='offline'?A.btn('恢复模拟连接','restore-source',`data-id="${A.e(id)}"`,'secondary','refresh'):'');
A.sourceFooter=id=>{const s=A.source(id);return `<div class="module-footer"><span>${A.icon('database',13)}${s?A.e(s.name):'未绑定来源'}</span><span>${s?.state==='connected'?'模拟更新时间 14:32':'尚未获取数据'}</span></div>`;};
A.modal = (title,body,footer='',wide=false,drawer=false) => `<dialog id="active-modal" class="dialog ${wide?'wide':''} ${drawer?'drawer':''}" aria-labelledby="dialog-title"><div class="dialog-inner"><header class="dialog-head"><div><h2 id="dialog-title">${title}</h2></div>${A.btn('','close-modal','aria-label="关闭弹窗"','icon-button','close')}</header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</div></dialog>`;
A.shell = body => {const team=A.state.edition==='team',nav=[['home','home','首页'],['workspaces','grid','我的工作台'],['datasources','database','数据源'],...(team?[['permissions','shield','成员与数据权限']]:[])];const w=A.workspace();return `<div class="app-shell ${A.ui.route==='editor'?'editing':''} ${A.ui.navOpen?'nav-open':''}"><aside class="sidebar"><button class="brand" data-action="nav" data-page="home" aria-label="Stackoryn 首页"><span class="brand-logo"><svg width="22" height="22" viewBox="0 0 24 24" fill="none"><path d="m12 3 9 5-9 5-9-5z" fill="white"/><path d="m3 11 9 5 9-5M3 15l9 5 9-5" stroke="white" stroke-width="2"/></svg></span><span>Stackoryn<span class="brand-period">.</span></span></button><button class="space-selector" data-action="nav" data-page="settings"><span class="square-avatar">${team?'T':'P'}</span><span><strong>${team?'团队工作空间':'个人工作空间'}</strong><small>${team?'Team · 设计预览':'Community · 自部署'}</small></span>${A.icon('down',14)}</button>${A.btn('创建工作台','create-workspace','','primary create-button','plus')}<nav aria-label="主导航">${nav.map(([route,icon,label])=>`<button class="nav-item ${(A.ui.route===route||route==='workspaces'&&['workspace','editor'].includes(A.ui.route))?'active':''}" data-action="nav" data-page="${route}">${A.icon(icon,18)}<span>${label}</span>${route==='workspaces'?`<small>${A.state.workspaces.length}</small>`:''}</button>`).join('')}</nav><div class="nav-section">最近使用</div><div class="recent-nav">${A.state.workspaces.slice(0,4).map(ws=>`<button class="recent-item ${A.ui.workspaceId===ws.id&&A.ui.route==='workspace'?'current':''}" data-action="open-workspace" data-id="${A.e(ws.id)}">${A.icon(ws.kind==='members'?'users':'table',15)}<span>${A.e(ws.title)}</span></button>`).join('')}</div><div class="sidebar-bottom"><div class="deployment-note">${A.icon(team?'cloud':'server',16)}<div><strong>${team?'云版体验预览':'后端直接连接数据库'}</strong><small>${team?'连接方案待定':'无需额外部署 Connector'}</small></div></div><button class="nav-item ${A.ui.route==='settings'?'active':''}" data-action="nav" data-page="settings">${A.icon('settings',18)}<span>设置与演示</span></button><div class="profile"><span class="avatar">S</span><div><strong>Stackoryn Demo</strong><small>${team?'多成员权限预览':'单用户 · 多数据源'}</small></div>${A.badge('MOCK')}</div></div></aside><div class="nav-scrim" data-action="toggle-nav"></div><main class="app-main"><header class="global-bar"><div class="breadcrumbs">${A.btn('','toggle-nav','aria-label="打开导航"','mobile-nav icon-button','collapse')}${A.icon('grid',15)}<span>${{home:'首页',workspace:'我的工作台',editor:'工作台编辑器',datasources:'数据源',permissions:'团队版设计',settings:'设置',workspaces:'我的工作台'}[A.ui.route]||'工作空间'}</span>${['workspace','editor'].includes(A.ui.route)?`${A.icon('chevron',12)}<span class="breadcrumb-current">${A.e(A.ui.draft?.title&&A.ui.route==='editor'?A.ui.draft.title:w?.title||'新建工作台')}</span>`:''}</div><div class="global-actions">${A.badge('<span class="dot gray"></span>Mock 交互原型')}${A.btn('演示设置','nav','data-page="settings"','ghost compact','settings')}<span class="avatar small">S</span></div></header>${A.ui.storageBlocked?A.notice('当前浏览器不允许本地保存；关闭后修改可能丢失。','warning'):''}${team&&['workspace','editor'].includes(A.ui.route)?`<div class="role-preview-bar">${A.icon('shield',16)}<strong>管理员权限预览</strong>${A.select('previewRole',A.ui.role,[['owner','数据管理员'],['support','客服'],['finance','财务'],['operator','门店运营']])}<span>仅模拟不同成员的可见结果，不改变登录身份。</span>${A.btn('编辑数据策略','nav','data-page="permissions"','text-button')}</div>`:''}${body}<div class="app-bottom-note">交互设计预览 · 全部使用虚构数据 · 不连接真实数据库</div></main></div><div id="toast-root" class="toast-container" aria-live="polite"></div>${A.dialogContent?A.dialogContent():''}`;};

A.renderWorkbench = (ws,preview=false) => {
 if(!ws)return A.empty('工作台不存在','从工作台目录选择一个已有工作台。');
 const q=A.queryOrders(ws,A.ui),profile=A.queryMembers(ws),activity=A.queryActivity(ws,A.ui.customer),p=A.currentPolicy();
 const allowedCost=(!p||p.fields.cost!=='hidden')&&ws.config.showCost,allowedPhone=(!p||p.fields.phone!=='hidden')&&ws.config.showPhone;
 const rows=q.rows||[],pageSize=6,maxPage=Math.max(1,Math.ceil(rows.length/pageSize));A.ui.page=Math.min(A.ui.page,maxPage);
 const selected=profile.rows?.find(r=>r.id===A.ui.customer);
 const ordersModule=()=>`<section class="surface orders-module"><div class="module-heading"><div><h3>${ws.kind==='orders'?'异常订单':'订单明细'}</h3>${q.ok?A.badge(rows.length):''}</div><div class="module-actions">${A.btn('来源','module-source','data-module="orders"','text-button','database')}${A.btn('导出 CSV','export-orders',`${!q.ok||!A.canExport()?'disabled title="当前角色不允许导出，或来源不可用"':''}`,'text-button','download')}</div></div>${q.ok?`<div class="table-toolbar"><div class="search-field">${A.icon('search',16)}${A.input('orderSearch',A.ui.search,'搜索订单、客户或可见邮箱')}</div><div class="filter-controls">${A.select('orderDays',A.ui.days,[['7','近 7 天'],['30','近 30 天'],['all','全部时间']])}${A.select('orderChannel',A.ui.channel,[['all','全部支付渠道'],['微信支付','微信支付'],['支付宝','支付宝'],['Stripe','Stripe']])}${A.select('orderSort',A.ui.sort,[['date','时间倒序'],['amount','金额从高到低']])}</div></div><div class="table-scroll"><table class="business-table"><thead><tr><th>订单编号</th><th>客户</th><th class="number">实付金额</th>${allowedCost?'<th class="number">成本</th>':''}<th>支付渠道</th><th>状态</th><th>创建时间</th><th></th></tr></thead><tbody>${rows.slice((A.ui.page-1)*pageSize,A.ui.page*pageSize).map(r=>`<tr data-action="order-detail" data-id="${r.id}" tabindex="0" role="button" aria-label="查看订单 ${r.id}"><td><span class="mono small-text">${r.id}</span><small class="table-secondary">${r.product}</small></td><td><span class="customer-cell"><span class="avatar tiny">${r.customer[0]}</span><span>${r.customer}<small class="table-secondary">${A.e(r.email||r.store)}</small></span></span></td><td class="number strong">${A.money(r.amount)}</td>${allowedCost?`<td class="number">${p?.fields.cost==='masked'?'••••':A.money(r.cost)}</td>`:''}<td><span class="payment-icon ${r.channel==='Stripe'?'stripe':r.channel==='支付宝'?'ali':'wechat'}">${r.channel==='Stripe'?'S':r.channel[0]}</span>${r.channel}</td><td>${A.badge(`<span class="status-mini-dot"></span>${r.status}`,r.status==='已完成'?'success':r.status==='履约失败'?'danger':r.status==='状态不一致'?'purple':'warning')}</td><td class="muted small-text">${A.date(r.createdAt)}</td><td>${A.icon('chevron',14)}</td></tr>`).join('')||`<tr><td colspan="8">${A.empty('没有符合条件的订单','调整筛选或搜索条件；当前角色的记录范围仍会生效。','search',A.btn('重置筛选','reset-filters','','secondary'))}</td></tr>`}</tbody></table></div><div class="table-pagination"><span>显示 ${rows.length?(A.ui.page-1)*pageSize+1:0}–${Math.min(rows.length,A.ui.page*pageSize)} 条，共 ${rows.length} 条</span><div>${A.btn('上一页','page-prev',A.ui.page===1?'disabled':'','ghost compact')}<span class="page-current">${A.ui.page}</span><span class="muted">/ ${maxPage}</span>${A.btn('下一页','page-next',A.ui.page===maxPage?'disabled':'','ghost compact')}</div></div>${A.sourceFooter(ws.bindings.orders)}`:A.sourceFailure(q,ws.bindings.orders)}</section>`;
 const profileModule=()=>`<section class="surface profile-module"><div class="module-heading"><div><h3>客户资料</h3>${A.badge(A.source(ws.bindings.profile)?.engine||'未绑定')}</div>${A.btn('','module-source','data-module="profile" aria-label="客户资料数据来源"','icon-button','database')}</div>${profile.ok?selected?`<div class="customer-profile"><span class="avatar large">${selected.name[0]}</span><h3>${selected.name}</h3><p class="mono">${selected.id}</p>${A.badge(selected.plan,'success')}</div><dl class="detail-fields compact"><div><dt>所属门店</dt><dd>${selected.store}</dd></div>${selected.email!==undefined?`<div><dt>邮箱 ${p?.fields.email==='masked'?A.badge('脱敏','warning'):''}</dt><dd>${A.e(selected.email)}</dd></div>`:''}${allowedPhone&&selected.phone!==undefined?`<div><dt>手机号 ${p?.fields.phone==='masked'?A.badge('脱敏','warning'):''}</dt><dd>${selected.phone}</dd></div>`:''}<div><dt>注册日期</dt><dd>${selected.registered}</dd></div><div><dt>订阅状态</dt><dd><span class="dot"></span>服务中</dd></div></dl>${A.btn('查看全部客户','clear-customer','','ghost full-width','arrow')}`:`<div class="customer-list-caption">点击客户，联动订单与使用数据</div><div class="customer-list">${profile.rows.map(r=>`<button data-action="select-customer" data-id="${r.id}" class="customer-list-item"><span class="avatar">${r.name[0]}</span><span><strong>${r.name}</strong><small>${r.plan} · ${r.store}</small></span>${A.icon('chevron',14)}</button>`).join('')||A.empty('当前没有可见客户','记录范围由演示策略决定。','users')}</div>`:A.sourceFailure(profile,ws.bindings.profile)}${profile.ok?A.sourceFooter(ws.bindings.profile):''}</section>`;
 const activityModule=()=>`<section class="surface activity-module"><div class="module-heading"><div><h3>产品使用趋势</h3><span class="muted small-text">近 12 天 · 按客户标识联动</span></div>${A.btn('来源','module-source','data-module="activity"','text-button','database')}</div>${activity.ok?`<div class="activity-layout"><div class="activity-summary"><div class="metric-label">授权范围内活跃客户</div><strong>${activity.activeCount}<small> 位</small></strong><p>示例活动数据，不随订单时间筛选变化</p></div><div class="chart-area" role="img" aria-label="近12天模拟产品使用趋势"><div class="chart-bars">${activity.values.map((v,i)=>`<div class="chart-bar-wrap"><span class="chart-bar" style="height:${v}%" title="第 ${i+1} 天：${v} 次"></span><small>${i%3===0?String(i+1).padStart(2,'0'):''}</small></div>`).join('')}</div><span class="chart-axis-label">10/28 — 11/08 · 每日访问次数</span></div></div>${A.sourceFooter(ws.bindings.activity)}`:A.sourceFailure(activity,ws.bindings.activity)}</section>`;
 if(ws.kind==='members')return `<div class="workbench-content">${profileModule()}</div>`;
 return `<div class="workbench-content">${ws.kind==='customer'?`<div class="linked-filter"><div>${A.icon('link',17)}<strong>客户联动</strong>${A.select('workspaceCustomer',A.ui.customer,[['all','全部授权客户'],...(profile.rows||[]).map(r=>[r.id,r.name+' · '+r.id])],!profile.ok?'disabled':'')}</div><span>使用已确认的 <code>customer_id</code> 映射 · 非跨库 JOIN</span>${A.btn('查看绑定','bindings','','text-button','settings')}</div>`:''}${q.ok?`<div class="metrics-strip"><div><span>匹配订单 ${A.icon('table',16)}</span><strong>${rows.length}<small> 笔</small></strong><p>当前筛选与记录权限范围</p></div><div><span>实付金额 ${A.icon('wallet',16)}</span><strong>${A.money(rows.reduce((s,r)=>s+r.amount,0))}</strong><p>按订单去重，不仅统计当前页</p></div><div><span>待核查订单 ${A.icon('clock',16)}</span><strong>${rows.filter(r=>r.status!=='已完成').length}<small> 笔</small></strong><p>履约超时、失败或状态不一致</p></div></div>`:A.notice('订单来源当前不可用，订单指标暂不显示；独立来源模块仍可正常使用。','warning','warning')}<div class="workspace-columns ${ws.kind==='orders'?'single':''}"><div class="workspace-primary">${ordersModule()}${ws.kind==='customer'&&ws.config.showActivity?activityModule():''}</div>${ws.kind==='customer'?`<aside class="workspace-secondary">${profileModule()}<div class="scope-hint">${A.icon('shield',17)}<div><strong>${p?'当前演示角色：'+p.label:'只读工作台'}</strong><p>${p?p.description+'。隐藏字段不会出现在此角色的详情和导出中。':'各模块独立读取已绑定来源。工作台不会自动切换到其他数据库。'}</p></div></div></aside>`:''}</div></div>`;
};
A.pages.workspace = () => {const ws=A.workspace();if(!ws)return `<div class="page">${A.empty('还没有工作台','创建一个工作台开始。','grid',A.btn('创建工作台','create-workspace','','primary','plus'))}</div>`;return `<div class="page workspace-page">${A.pageHead('',`${A.e(ws.title)} ${A.badge('已保存','subdued')}`,A.e(ws.description),A.btn('刷新','refresh-workspace','','secondary','refresh')+A.btn('用 AI 修改','edit-workspace','','primary','spark'))}<div class="workspace-meta"><div class="source-pills">${ws.datasourceIds.map(A.sourceChip).join('')}</div><span class="meta-divider"></span><span>${A.icon('lock',13)}只读</span><span>v${ws.version}</span>${A.btn('数据说明','data-notes','','text-button','info')}</div>${A.renderWorkbench(ws)}</div>`;};

A.pages.workspaces = () => {const q=A.ui.workspaceSearch||'',filter=A.ui.workspaceSource||'all';const rows=A.state.workspaces.filter(w=>w.title.includes(q)&&(filter==='all'||w.datasourceIds.includes(filter)));return `<div class="page">${A.pageHead('WORKSPACES','我的工作台','把重复的业务查询，变成随时可以打开的工具。',A.btn('创建工作台','create-workspace','','primary','plus'))}<div class="directory-toolbar"><div class="search-field">${A.icon('search',16)}${A.input('workspaceSearch',q,'搜索工作台')}</div>${A.select('workspaceSource',filter,[['all','全部数据源'],...A.state.sources.map(s=>[s.id,s.name])])}<span class="muted">${rows.length} 个工作台</span></div><div class="surface workspace-directory"><div class="directory-head"><span>工作台</span><span>使用的数据源</span><span>修改时间</span><span></span></div>${rows.map(w=>`<div class="workspace-directory-row"><button class="directory-name" data-action="open-workspace" data-id="${w.id}"><span class="workspace-icon">${A.icon(w.kind==='members'?'users':w.kind==='customer'?'grid':'table',21)}</span><span><strong>${A.e(w.title)}</strong><small>${A.e(w.description)}</small></span></button><div class="source-pills">${w.datasourceIds.map(id=>{const s=A.source(id);return s?`<span class="source-short" title="${A.e(s.name)}">${A.engineIcon(s.engine)}${A.e(s.name)}</span>`:''}).join('')}</div><span class="muted small-text">${A.date(w.updated)}</span><div class="row-actions">${A.btn('','rename-workspace',`data-id="${w.id}" aria-label="重命名 ${A.e(w.title)}"`,'icon-button','edit')}${A.btn('','copy-workspace',`data-id="${w.id}" aria-label="复制 ${A.e(w.title)}"`,'icon-button','copy')}${A.btn('','delete-workspace',`data-id="${w.id}" aria-label="删除 ${A.e(w.title)}"`,'icon-button','trash')}</div></div>`).join('')||A.empty('没有找到工作台','换个名称或数据源试试。','search')}</div><div class="inline-footnote">${A.icon('info',15)}删除工作台不会删除数据库记录；复制工作台不会复制更高的数据权限。</div></div>`;};

A.pages.home=()=>{const selected=A.ui.createSources||['orders','members','events'];return `<div class="page home-page"><div class="home-heading"><div><div class="eyebrow">YOUR BUSINESS, CONNECTED</div><h1>今天，从哪个工作台开始？</h1><p>连接已有数据，把零散的业务查询变成可以反复使用的工具。</p></div><span class="home-edition">${A.icon('server',18)}${A.state.edition==='community'?'Community · 用户后端直连':'Team · 体验预览'}</span></div><section class="home-create"><div class="home-create-top"><span class="small-spark">${A.icon('spark',20)}</span><h2>描述需求，创建一个业务工作台</h2></div><textarea id="homePrompt" data-model="homePrompt" rows="2" placeholder="例如：把会员资料、订单和使用情况放在一起，做一个客户业务总览……">${A.e(A.ui.homePrompt||'')}</textarea><div class="composer-bottom"><button class="select-sources-button" data-action="select-create-sources">${A.icon('database',16)}<span>使用 ${selected.length} 个数据源</span><span class="mini-engines">${[...new Set(selected.map(id=>A.source(id)?.engine).filter(Boolean))].map(A.engineIcon).join('')}</span>${A.icon('down',14)}</button>${A.btn('创建工作台','generate-home','','primary','arrow')}</div></section><div class="suggestion-row"><span>从一个具体任务开始</span>${A.btn('客户业务总览','template','data-template="customer"','suggestion','users')}${A.btn('异常订单排查','template','data-template="orders"','suggestion','table')}${A.btn('高价值客户检索','template','data-template="members"','suggestion','search')}</div><section class="home-section"><div class="section-heading"><div><h2>继续你的工作</h2><span>已保存的工作台，无需重新询问 AI</span></div>${A.btn('查看全部','nav','data-page="workspaces"','text-button','arrow')}</div><div class="workspace-cards">${A.state.workspaces.slice(0,3).map(w=>`<button class="workspace-card" data-action="open-workspace" data-id="${w.id}"><div class="card-top"><span class="workspace-icon">${A.icon(w.kind==='customer'?'grid':w.kind==='orders'?'table':'users',23)}</span>${A.icon('arrow',18)}</div><h3>${A.e(w.title)}</h3><p>${A.e(w.description)}</p><div class="card-bottom"><span class="mini-engines">${[...new Set(w.datasourceIds.map(id=>A.source(id)?.engine).filter(Boolean))].map(A.engineIcon).join('')}</span><span>${w.datasourceIds.length} 个数据源</span><span>v${w.version}</span></div></button>`).join('')||A.empty('还没有保存的工作台','上方描述需求，或先体验示例。','grid')}</div></section><section class="home-section"><div class="section-heading"><div><h2>数据已就位</h2><span>数据库类型不同，也能出现在同一个业务界面</span></div>${A.btn('管理数据源','nav','data-page="datasources"','text-button','arrow')}</div><div class="surface home-sources">${A.state.sources.slice(0,4).map(s=>`<button class="home-source" data-action="source-detail" data-id="${s.id}">${A.engineIcon(s.engine)}<span><strong>${A.e(s.name)}</strong><small>${s.engine} · ${s.environment}</small></span><span class="dot ${s.state==='offline'?'red':''}"></span></button>`).join('')}</div></section></div>`;};

A.pages.datasources=()=>{const q=A.ui.sourceSearch,filter=A.ui.engineFilter,sources=A.state.sources.filter(s=>(s.name+' '+s.database).toLowerCase().includes(q.toLowerCase())&&(filter==='all'||s.engine===filter));const team=A.state.edition==='team';return `<div class="page sources-page">${A.pageHead('DATA SOURCES','数据源','管理数据库连接。在同一个工作台中，按需组合不同来源的数据。',A.btn('添加数据源','add-source','','primary','plus'))}<div class="connection-model">${A.icon(team?'cloud':'server',21)}<div><strong>${team?'团队版连接方式待定':'开源版 · 应用后端直连'}</strong><span>${team?'此界面仅演示数据源管理；不预设云端托管凭证或独立连接节点。':'由你部署的 Stackoryn 后端连接数据库，无需额外安装 Connector。当前为模拟连接。'}</span></div>${A.btn('了解部署边界','nav','data-page="settings"','text-button','arrow')}</div><div class="source-stat-row"><div><strong>${A.state.sources.length}</strong><span>个数据源</span></div><div><span class="dot"></span><strong>${A.state.sources.filter(s=>s.state==='connected').length}</strong><span>连接可用</span></div><div><span class="dot red"></span><strong>${A.state.sources.filter(s=>s.state==='offline').length}</strong><span>暂时离线</span></div><div><strong>${new Set(A.state.sources.map(s=>s.engine)).size}</strong><span>种数据库类型</span></div></div><div class="directory-toolbar"><div class="search-field">${A.icon('search',16)}${A.input('sourceSearch',q,'搜索连接名称或数据库名')}</div><div class="segmented">${[['all','全部'],['PostgreSQL','PostgreSQL'],['MySQL','MySQL'],['ClickHouse','ClickHouse']].map(([v,t])=>`<button data-action="filter-engine" data-value="${v}" class="${filter===v?'selected':''}">${t}</button>`).join('')}</div></div><div class="surface sources-list"><div class="source-table-head"><span>数据源</span><span>环境与访问</span><span>连接状态</span><span>使用情况</span><span></span></div>${sources.map(s=>{const refs=A.state.workspaces.filter(w=>w.datasourceIds.includes(s.id));return `<div class="source-row"><button class="source-identity" data-action="source-detail" data-id="${s.id}">${A.engineIcon(s.engine)}<span><strong>${A.e(s.name)}</strong><small>${s.engine} <span>·</span> <code>${A.e(s.database)}</code></small></span></button><div>${A.badge(s.environment,s.environment==='生产'?'blue':'neutral')}<small class="table-secondary">${A.icon('lock',12)}只读访问</small></div><div>${A.status(s.state)}<small class="table-secondary">模拟状态 · ${s.updated}</small></div><button class="usage-link" data-action="source-detail" data-id="${s.id}" data-tab="usage">${refs.length} 个工作台${A.icon('chevron',13)}</button><div class="row-actions">${A.btn('管理','source-detail',`data-id="${s.id}"`,'secondary compact')}${A.btn('','edit-source',`data-id="${s.id}" aria-label="编辑 ${A.e(s.name)}"`,'icon-button','edit')}</div></div>`}).join('')||A.empty('没有匹配的数据源','支持同一种数据库创建多条连接。','database',A.btn('添加数据源','add-source','','primary','plus'))}</div><div class="source-guide-grid"><div><span class="guide-number">01</span><h3>连接彼此独立</h3><p>生产、测试库分别管理，不会因为页面切换而替换工作台的执行目标。</p></div><div><span class="guide-number">02</span><h3>每个模块明确来源</h3><p>客户资料来自会员库，订单来自交易库。按查询绑定，而非全局切换。</p></div><div><span class="guide-number">03</span><h3>密码不在浏览器保存</h3><p>原型不接收真实凭证；正式开源版交由用户部署的后端保存和使用。</p></div></div></div>`;};

A.startEditor=(id,prompt='',kind='customer',sources)=>{
 const original=id?A.state.workspaces.find(w=>w.id===id):null;
 const ds=sources||A.state.sources.filter(s=>s.state==='connected').map(s=>s.id);
 const choose=domain=>ds.find(sid=>A.source(sid)?.domain===domain)||'';
 const base=original?structuredClone(original):{id:A.uid('workspace'),title:kind==='customer'?'客户业务总览':kind==='members'?'高价值客户检索':'异常订单排查',description:kind==='customer'?'把客户资料、订单和使用情况放在同一个工作台。':kind==='orders'?'定位已支付但未履约的订单，核查业务异常。':'查看会员资料与订阅状态。',kind,datasourceIds:ds,bindings:kind==='customer'?{orders:choose('orders'),profile:choose('members'),activity:choose('events')}:kind==='orders'?{orders:choose('orders')}:{profile:choose('members')},version:original?.version||0,config:{showActivity:kind==='customer'&&!!choose('events'),showPhone:true,showCost:false,defaultDays:'30'},updated:A.now};
 A.ui.editorOriginal=original?structuredClone(original):null;
 A.ui.draft=original&&A.state.drafts[id]?structuredClone(A.state.drafts[id]):base;
 A.ui.editorTab='chat';A.ui.mobileEditor='preview';A.ui.editorDirty=!original||JSON.stringify(base)!==JSON.stringify(A.ui.draft);
 A.ui.messages=[...(prompt?[{role:'user',text:prompt}]:[]),{role:'assistant',text:original?'可以继续描述你希望怎样调整这个工作台。修改会先进入草稿，保存后才影响正式界面。':'已使用预设模板生成草稿。每个模块单独绑定数据源，你可以在「数据与模块」中检查来源。',changes:['订单查询、客户查询与行为查询分别执行','客户联动使用已确认的 customer_id 映射','所有查询和 AI 响应均为本地模拟']}];
 A.ui.workspaceId=base.id;A.ui.editorPrompt='';A.ui.customer='all';A.ui.search='';A.ui.page=1;
 A.navigate('editor',base.id,true);
};
A.pages.editor=()=>{const ws=A.ui.draft;if(!ws)return `<div class="page">${A.empty('尚未创建草稿','从首页描述需求，或选择已有工作台进行修改。','grid',A.btn('创建工作台','create-workspace','','primary'))}</div>`;const dirty=A.ui.editorDirty;return `<div class="editor-page"><div class="editor-toolbar"><div><button class="back-button" data-action="leave-editor" aria-label="退出编辑">${A.icon('arrow',18)}</button><span class="editor-title">${A.e(ws.title)}</span>${A.badge(dirty?'未保存草稿':'草稿已保存',dirty?'warning':'success')}<span class="editor-revision">基于 v${A.ui.editorOriginal?.version||0}</span></div><div>${A.btn('放弃修改','discard-editor','','secondary')}${A.btn(A.ui.editorOriginal?'保存更新':'保存工作台','save-workspace',A.ui.generating?'disabled':'','primary','check')}</div></div><div class="mobile-editor-tabs segmented"><button data-action="mobile-editor" data-tab="chat" class="${A.ui.mobileEditor==='chat'?'selected':''}">对话与配置</button><button data-action="mobile-editor" data-tab="preview" class="${A.ui.mobileEditor==='preview'?'selected':''}">工作台预览</button></div><div class="editor-columns mobile-${A.ui.mobileEditor}"><aside class="editor-panel"><div class="editor-tabs"><button class="${A.ui.editorTab==='chat'?'selected':''}" data-action="editor-tab" data-tab="chat">${A.icon('spark',16)}AI 修改</button><button class="${A.ui.editorTab==='data'?'selected':''}" data-action="editor-tab" data-tab="data">${A.icon('database',16)}数据与模块</button></div>${A.ui.editorTab==='chat'?`<div class="chat-messages">${A.ui.messages.map(m=>`<div class="message ${m.role}">${m.role==='assistant'?`<div class="message-author"><span class="assistant-avatar">${A.icon('spark',14)}</span>Stackoryn <span>模拟响应</span></div>`:''}<div class="message-text">${A.e(m.text)}</div>${m.changes?`<div class="change-list">${m.changes.map(t=>`<div>${A.icon('check',13)}<span>${A.e(t)}</span></div>`).join('')}</div>`:''}</div>`).join('')}${A.ui.generating?`<div class="generation-progress"><span class="spinner"></span><span>正在更新预览草稿…</span>${A.btn('停止','stop-generation','','text-button')}</div>`:''}<div class="chat-tip">${A.icon('lock',14)}AI 不会改变数据权限，也不会执行数据库写入。</div></div><div class="editor-composer"><div class="prompt-quick">${A.btn('增加使用趋势','editor-suggest','data-prompt="增加使用趋势"','suggestion')}${A.btn('隐藏手机号','editor-suggest','data-prompt="隐藏手机号"','suggestion')}</div><div class="editor-prompt-box"><textarea id="editorPrompt" data-model="editorPrompt" rows="3" placeholder="描述如何修改，比如：隐藏手机号……">${A.e(A.ui.editorPrompt||'')}</textarea><div><span>仅修改当前草稿</span>${A.btn('','send-editor',`${A.ui.generating?'disabled':''} aria-label="发送修改指令"`,'primary icon-button','arrow')}</div></div></div>`:`<div class="editor-data-panel"><div class="section-mini-head"><h3>工作台数据源</h3>${A.btn('选择','choose-editor-sources','','text-button','plus')}</div><div class="editor-source-list">${ws.datasourceIds.map(id=>A.sourceChip(id)).join('')||'<p class="muted">还没有选择数据源</p>'}</div><p class="small-note">选择来源只确定可用范围。每个模块仍需绑定具体来源与查询。</p><div class="section-mini-head"><h3>模块与查询绑定</h3></div>${Object.keys(ws.bindings).map(key=>`<div class="binding-card"><div>${A.icon(key==='orders'?'table':key==='profile'?'users':'chart',16)}<strong>${A.bindingLabel[key]}</strong><code>q_${key}</code></div>${A.select('binding-'+key,ws.bindings[key]||'',[['','请选择兼容数据源'],...A.state.sources.filter(s=>ws.datasourceIds.includes(s.id)&&s.domain===A.bindingDomain[key]).map(s=>[s.id,s.name+' · '+s.engine])])}<small>${key==='orders'?'orders · 按 customer_id 筛选':key==='profile'?'customers · id → customer_id':'user_events · user_id → customer_id'}</small></div>`).join('')}<div class="relation-card">${A.icon('link',17)}<div><strong>客户标识映射</strong><p>customers.id → orders.customer_id<br>customers.id → user_events.user_id</p><small>示例中已确认 · 不是自动猜测关联</small></div></div><div class="section-mini-head"><h3>显示配置</h3></div>${[['showPhone','显示手机号'],['showCost','显示订单成本'],['showActivity','显示使用趋势']].map(([key,label])=>`<label class="switch-row"><span>${label}</span><input type="checkbox" id="config-${key}" data-model="config-${key}" ${ws.config[key]?'checked':''}></label>`).join('')}<p class="small-note">显示列属于布局配置，不能覆盖成员的数据权限。</p></div>`}</aside><div class="editor-preview"><div class="preview-bar"><div><span class="dot"></span><strong>实时预览</strong>${A.badge('草稿')}</div><span>${ws.datasourceIds.length} 个来源 · 模拟数据 · 只读</span>${A.btn('数据说明','data-notes','','icon-button','info')}</div><div class="preview-content">${A.renderWorkbench(ws,true)}</div></div></div></div>`;};

A.pages.permissions=()=>{if(A.state.edition!=='team')return `<div class="page">${A.pageHead('TEAM DESIGN','成员与数据权限','开源版保持单用户。这一页是独立的团队权限设计预览。')}<div class="surface edition-intro">${A.icon('shield',40)}<h2>不同成员，看到不同的数据</h2><p>团队版将提供用户组、字段权限、记录范围和导出控制。它不会改变开源版的直连流程，也不预设云版连接架构。</p>${A.btn('进入团队权限预览','enter-team','','primary','arrow')}<small>仅切换原型视图，不创建组织、不邀请成员。</small></div></div>`;const role=A.ui.permissionRole||'support',p=A.ui.policyDraft||A.state.policies[role],changed=A.ui.policyDirty;const selected=(key,val,options)=>A.select(key,val,options);return `<div class="page permissions-page">${A.pageHead('TEAM · DESIGN PREVIEW','成员与数据权限','同一个工作台，按成员身份返回允许访问的数据。',A.btn('预览成员视角','policy-preview',changed?'disabled title="请先保存策略草稿"':'','secondary','eye')+A.btn('保存策略','save-policy',!changed?'disabled':'','primary','check'))}${A.notice('这是团队版的权限交互演示，不是生产鉴权。数据库连接方案仍待确定；正式规则必须由可信后端执行。','subtle','shield')}<div class="permissions-layout"><aside class="surface roles-panel"><div class="panel-label">业务角色 / 用户组</div>${Object.entries(A.state.policies).map(([id,policy])=>`<button class="role-card ${id===role?'selected':''}" data-action="permission-role" data-role="${id}"><span class="avatar">${policy.label[0]}</span><span><strong>${policy.label}</strong><small>${policy.description}</small></span>${id===role?A.icon('check',15):''}</button>`).join('')}<div class="role-footer"><span>${A.icon('users',16)}3 个演示角色</span><p>成员管理与数据读取权限分开。组织管理员不默认获得全部原始数据。</p></div></aside><section class="surface policy-panel"><div class="policy-heading"><div><h2>${p.label}</h2><p>${p.description}</p></div>${A.badge(changed?'有未保存修改':'已保存示例策略',changed?'warning':'success')}</div><div class="policy-tabs"><button data-action="policy-tab" data-tab="fields" class="${A.ui.scopeTab==='fields'?'selected':''}">字段与记录</button><button data-action="policy-tab" data-tab="sources" class="${A.ui.scopeTab==='sources'?'selected':''}">数据源与操作</button><button data-action="policy-tab" data-tab="members" class="${A.ui.scopeTab==='members'?'selected':''}">关联成员</button></div>${A.ui.scopeTab==='fields'?`<div class="policy-section"><h3>字段访问</h3><p>隐藏不只是取消勾选列；详情、复制、导出与 AI 也必须遵守。</p><table class="policy-table"><thead><tr><th>字段</th><th>访问方式</th><th>示例结果</th></tr></thead><tbody><tr><td><strong>订单编号 / 状态</strong><small>orders.id / orders.status</small></td><td>${A.badge('原文可见','success')}</td><td><code>ORD-261108-1048</code></td></tr>${[['phone','客户手机号','customers.phone','13820105678'],['email','客户邮箱','customers.email','demo@example.com'],['cost','订单成本','orders.cost','420.00']].map(([key,label,col,value])=>`<tr><td><strong>${label}</strong><small>${col}</small></td><td>${selected('policy-field-'+key,p.fields[key],[['raw','原文可见'],['masked','脱敏可见'],['hidden','不可访问']])}</td><td><span class="field-example ${p.fields[key]==='hidden'?'muted':''}">${p.fields[key]==='hidden'?'不返回字段':p.fields[key]==='masked'?(key==='cost'?'••••':A.mask(value,key)):value}</span></td></tr>`).join('')}</tbody></table></div><div class="policy-section"><h3>记录范围</h3><p>同一限制用于列表、详情、指标和导出，不能通过筛选放宽。</p>${selected('policy-rowScope',p.rowScope,[['all','全部已授权记录'],['assigned','仅本人负责的记录'],['store','仅所属门店的记录']])}<div class="rule-preview">${A.icon('code',16)}<code>${p.rowScope==='all'?'在已授权数据源和数据集中读取':p.rowScope==='assigned'?'orders.assignee_id = current_user.id':'orders.store_id IN current_user.store_ids'}</code></div><small class="muted">当前示例：客服 support-01，门店运营属于杭州门店。正式身份属性由后端确认。</small></div>`:A.ui.scopeTab==='sources'?`<div class="policy-section"><h3>允许使用的数据源</h3><p>工作台被分享，不意味着数据源读取权同时被授予。</p><div class="permission-sources">${A.state.sources.map(s=>`<label><input type="checkbox" id="policy-source-${s.id}" data-model="policy-source-${s.id}" ${p.allowedSources.includes(s.id)?'checked':''}>${A.engineIcon(s.engine)}<span><strong>${A.e(s.name)}</strong><small>${s.engine}</small></span></label>`).join('')}</div></div><div class="policy-section"><h3>额外操作</h3><label class="switch-row"><span><strong>允许导出</strong><small>仍按字段与记录规则返回结果</small></span><input id="policy-export" data-model="policy-export" type="checkbox" ${p.export?'checked':''}></label><label class="switch-row"><span><strong>敏感字段允许交给 AI</strong><small>独立授权，不因用户可见而默认允许</small></span><input id="policy-aiSensitive" data-model="policy-aiSensitive" type="checkbox" ${p.aiSensitive?'checked':''}></label>${A.notice('本原型没有发送任何数据给模型。AI 数据授权开关只演示配置，不代表已完成数据安全机制。','subtle','info')}</div>`:`<div class="policy-section"><h3>关联成员</h3><p>用于检查角色与记录范围的样例身份，不是真实账号。</p><div class="member-row"><span class="avatar">${p.label[0]}</span><span><strong>${p.label}演示成员</strong><small>${role==='support'?'support-01':role==='operator'?'store-operator-01':'finance-01'} · ${role==='operator'?'杭州门店':'示例组织'}</small></span>${A.badge('模拟成员')}</div>${A.notice('成员邀请、登录认证、撤权和审计需要在真实后端接入时实现。','subtle')}</div>`}<div class="policy-bottom">${A.icon('lock',15)}默认拒绝 · 显式禁止优先 · 前端不是安全边界</div></section></div></div>`;};

A.pages.settings=()=>`<div class="page settings-page">${A.pageHead('SETTINGS','设置与演示','区分产品部署模式与当前的设计预览。')}<div class="settings-grid"><section class="surface settings-card"><div class="section-heading"><div><h2>产品模式</h2><span>切换原型中的导航与可用设计界面</span></div></div><button class="edition-option ${A.state.edition==='community'?'selected':''}" data-action="set-edition" data-edition="community"><span class="edition-icon">${A.icon('server',24)}</span><span><strong>Community 开源版 ${A.badge('当前开发重点','success')}</strong><small>单用户 · 自部署后端直连 · 多数据库、多数据源</small></span>${A.state.edition==='community'?A.icon('check',20):A.icon('chevron',17)}</button><button class="edition-option ${A.state.edition==='team'?'selected':''}" data-action="set-edition" data-edition="team"><span class="edition-icon">${A.icon('users',24)}</span><span><strong>团队版设计预览 ${A.badge('未接入')}</strong><small>预览成员、字段与记录权限；云端连接方案待定</small></span>${A.state.edition==='team'?A.icon('check',20):A.icon('chevron',17)}</button></section><section class="surface settings-card"><h2>开源版的访问路径</h2><div class="architecture-path"><span>${A.icon('grid',20)}浏览器</span>${A.icon('arrow',18)}<span class="highlight">${A.icon('server',20)}你的 Stackoryn 后端</span>${A.icon('arrow',18)}<span>${A.icon('database',20)}多个数据库</span></div><p class="muted">正式产品由同一后端保存连接与工作台。其他设备访问这套服务即可使用，数据库不与浏览器直接通信。</p>${A.notice('本轮是纯前端 Mock。配置只保存在当前浏览器，没有跨设备同步，也不验证数据库网络连通性。','subtle')}</section><section class="surface settings-card"><h2>局部失败演示</h2><p class="muted">只断开一个来源，检查多源工作台的其他模块是否仍可用。</p><div class="simulation-rows">${A.state.sources.map(s=>`<div><span>${A.engineIcon(s.engine)}${A.e(s.name)}</span>${A.btn(s.state==='connected'?'模拟断开':'恢复连接','toggle-source',`data-id="${s.id}"`,'secondary compact',s.state==='connected'?'logout':'refresh')}</div>`).join('')}</div>${A.btn('打开客户业务总览','open-workspace','data-id="customer-360"','text-button','arrow')}</section><section class="surface settings-card"><h2>本地演示数据</h2><p class="muted">工作台、数据源配置与权限策略保存在独立的 v0.2 存储空间，不覆盖之前的 v0.1 原型数据。</p><div class="design-boundaries"><div>${A.icon('check',15)}没有真实数据库或 AI 请求</div><div>${A.icon('check',15)}连接密码不写入本地存储</div><div>${A.icon('check',15)}权限仅供交互验证，不是生产鉴权</div></div>${A.btn('重置演示数据','reset-demo','','danger','refresh')}</section></div></div>`;

A.dialogContent=()=>{const modal=A.ui.modal;if(!modal)return '';const ws=A.ui.route==='editor'?A.ui.draft:A.workspace(),team=A.state.edition==='team';
 if(modal==='source-detail'){
  const s=A.source(A.ui.sourceId);if(!s)return '';const tab=A.ui.sourceTab||'overview',refs=A.state.workspaces.filter(w=>w.datasourceIds.includes(s.id));
  return A.modal('数据源详情',`<div class="source-detail-title">${A.engineIcon(s.engine)}<div><h3>${A.e(s.name)}</h3><p>${s.engine} · ${A.e(s.database)}</p></div>${A.status(s.state)}</div><div class="policy-tabs">${[['overview','连接配置'],['schema','可用表结构'],['usage','使用情况']].map(([k,l])=>`<button data-action="source-tab" data-tab="${k}" class="${tab===k?'selected':''}">${l}${k==='usage'?` (${refs.length})`:''}</button>`).join('')}</div>${tab==='overview'?`<dl class="detail-fields"><div><dt>连接方式</dt><dd>${team?'云版方案待定':'应用后端直连'}</dd></div><div><dt>数据库类型</dt><dd>${s.engine}</dd></div><div><dt>主机</dt><dd><code>${A.e(s.host)}</code></dd></div><div><dt>端口 / 数据库</dt><dd>${s.port} / ${A.e(s.database)}</dd></div><div><dt>环境</dt><dd>${s.environment}</dd></div><div><dt>访问模式</dt><dd>${A.badge('只读','success')}</dd></div><div><dt>TLS</dt><dd>${s.ssl?'启用（配置示例）':'未启用（配置示例）'}</dd></div></dl>${A.notice('没有保存任何真实连接凭证。连接状态、表结构和查询结果全部为模拟。','subtle','lock')}`:tab==='schema'?`<p class="muted small-text">演示结构，不来自真实数据库扫描。当前允许 ${s.tables.length} 张表。</p><div class="schema-list">${s.tables.map(t=>`<details open><summary>${A.icon('table',15)}<strong>${A.e(t)}</strong><small>示例</small></summary><div><code>${({orders:'id · customer_id · amount · cost · status · store_id',payments:'id · order_id · channel · pay_status',customers:'id · name · phone · email · store_id',subscriptions:'id · customer_id · plan · expires_at',user_events:'id · user_id · event_name · occurred_at'})[t]||'id · created_at'}</code></div></details>`).join('')}</div>`:`<div class="usage-workspaces">${refs.map(w=>`<button data-action="open-workspace" data-id="${w.id}">${A.icon('grid',20)}<span><strong>${A.e(w.title)}</strong><small>${Object.entries(w.bindings).filter(([k,v])=>v===s.id).map(([k])=>A.bindingLabel[k]).join('、')}</small></span>${A.icon('arrow',16)}</button>`).join('')||A.empty('暂未被工作台使用','可以在创建工作台时选择这个数据源。','grid')}</div>`}`,
   `${A.btn('删除','delete-source',`data-id="${s.id}" ${refs.length?'disabled title="已被工作台引用，需先解除绑定"':''}`,'danger','trash')}<span class="footer-spacer"></span>${A.btn('编辑连接','edit-source',`data-id="${s.id}"`,'secondary','edit')}${A.btn(s.state==='connected'?'模拟断开':'恢复模拟连接','toggle-source',`data-id="${s.id}"`,'primary',s.state==='connected'?'logout':'refresh')}`,false,true);
 }
 if(modal==='source-form'){
  const f=A.ui.sourceForm,step=A.ui.sourceStep||1,engines=[['PostgreSQL','关系型数据库','5432'],['MySQL','关系型数据库','3306'],['ClickHouse','分析型数据库','8443']];const tables={orders:['orders','payments'],members:['customers','subscriptions'],events:['user_events']}[f.domain]||[];
  const stepper=`<div class="stepper">${['选择类型','连接配置','访问范围'].map((label,i)=>`<div class="${step===i+1?'current':step>i+1?'complete':''}"><span>${step>i+1?'✓':i+1}</span>${label}</div>`).join('')}</div>`;
  let body=step===1?`<h3 class="form-section-title">选择数据库类型</h3><p class="muted">同一种数据库可以创建多个连接，分别管理生产和测试环境。</p><div class="engine-options">${engines.map(([name,desc])=>`<button data-action="select-engine" data-engine="${name}" class="${f.engine===name?'selected':''}">${A.engineIcon(name)}<span><strong>${name}</strong><small>${desc}</small></span>${f.engine===name?A.icon('check',18):''}</button>`).join('')}</div>${A.notice('当前支持三种类型的模拟流程，不代表已接入真实驱动。','subtle')}`:step===2?`<div class="form-grid">${A.field('连接名称',A.input('ds-name',f.name,'例如：订单生产库','autocomplete="off"'))}${A.field('环境',A.select('ds-environment',f.environment,[['生产','生产'],['测试','测试'],['分析','分析']]))}${A.field('主机地址',A.input('ds-host',f.host,'db.internal.example','autocomplete="off"'))}${A.field('端口',A.input('ds-port',f.port,'5432','type="number" min="1" max="65535"'))}${A.field('数据库名',A.input('ds-database',f.database,'commerce','autocomplete="off"'))}${A.field('模拟账号',A.input('ds-username',f.username,'demo_readonly','autocomplete="off"'))}${A.field('密码（仅演示）',A.input('ds-password',f.password,'不要填写真实密码','type="password" autocomplete="new-password"'),'仅保留在当前弹窗，不写入本地存储。')}${A.field('示例业务数据',A.select('ds-domain',f.domain,[['orders','订单与支付'],['members','会员与订阅'],['events','用户行为']]))}</div><label class="checkbox-line"><input id="ds-ssl" data-model="ds-ssl" type="checkbox" ${f.ssl?'checked':''}>启用 TLS / SSL（配置示例）</label><div class="test-connection-row">${A.btn(A.ui.testing?'正在模拟测试…':'测试连接','test-source',A.ui.testing?'disabled':'','secondary','refresh')}<label><input id="ds-fail" data-model="ds-fail" type="checkbox" ${f.fail?'checked':''}>模拟连接失败</label></div>${A.ui.testResult==='success'?A.notice('模拟连接成功。下一步选择可用表；不会实际连接数据库。','success','check'):A.ui.testResult==='error'?A.notice('模拟连接失败：主机不可达。关闭“模拟连接失败”后可重试。','danger','warning'):A.ui.formError?A.notice(A.e(A.ui.formError),'danger','warning'):''}`:`<div class="connection-success"><span>${A.icon('check',24)}</span><div><strong>连接测试已通过（模拟）</strong><small>${A.e(f.name)} · ${f.engine} · ${A.e(f.database)}</small></div>${A.badge('只读','success')}</div><h3 class="form-section-title">允许工作台使用的表</h3><p class="muted">限定可用范围。正式版本需要在后端查询层执行这些限制。</p><div class="scope-tables">${tables.map(t=>`<label><input id="ds-table-${t}" data-model="ds-table-${t}" type="checkbox" ${f.tables.includes(t)?'checked':''}>${A.icon('table',16)}<code>${t}</code><small>示例结构</small></label>`).join('')}</div>${A.notice(team?'云端连接方式另行确定，这里只保存模拟元数据。':'正式开源版由你的 Stackoryn 后端保存凭证、建立连接。其他设备访问同一服务，不需要重新添加连接。','subtle','server')}`;
  return A.modal(A.ui.editSourceId?'编辑数据库连接':'添加数据源',stepper+body,`${A.btn(step===1?'取消':'上一步',step===1?'close-modal':'source-step-back','','secondary')}<span class="footer-spacer"></span>${step===3?A.btn('保存数据源','save-source',!f.tables.length?'disabled':'','primary','check'):A.btn('下一步','source-step-next',step===2&&A.ui.testResult!=='success'?'disabled':'','primary','arrow')}`,true);
 }
 if(modal==='source-picker'){
  const set=A.ui.pickerIds||[],context=A.ui.pickerContext;
  return A.modal('选择工作台数据源',`<p class="muted">可选择多个来源。每个模块独立查询；不执行任意跨库 JOIN。</p><div class="source-picker-list">${A.state.sources.map(s=>`<label class="source-picker-item ${set.includes(s.id)?'selected':''}"><input id="pick-${s.id}" data-model="pick-${s.id}" type="checkbox" ${set.includes(s.id)?'checked':''}>${A.engineIcon(s.engine)}<span><strong>${A.e(s.name)}</strong><small>${s.engine} · ${s.environment} · ${A.e(s.database)}</small></span>${A.status(s.state)}</label>`).join('')}</div>${context==='editor'?A.notice('移除正在使用的数据源后，对应模块将进入“尚未绑定”状态。不会自动换到另一个数据库。','subtle'):''}`,`${A.btn('取消','close-modal')}<span class="footer-spacer"></span><span class="muted">已选 ${set.length} 个</span>${A.btn('确认选择','apply-source-picker',!set.length?'disabled':'','primary','check')}`,true);
 }
 if(modal==='bindings'||modal==='module-source'){
  const key=A.ui.moduleKey,entries=Object.entries(ws.bindings).filter(([k])=>modal==='bindings'||k===key);
  return A.modal(modal==='bindings'?'数据来源与联动关系':A.bindingLabel[key]+' · 数据来源',`<div class="binding-summary">${entries.map(([k,id])=>`<div class="binding-summary-row"><span class="workspace-icon">${A.icon(k==='orders'?'table':k==='profile'?'users':'chart',20)}</span><div><strong>${A.bindingLabel[k]}</strong><small><code>q_${k}</code> → ${A.e(A.source(id)?.name||'尚未绑定')}</small></div>${A.badge(A.source(id)?.engine||'未配置')}</div>`).join('')}</div><div class="rule-preview">${A.icon('link',17)}<code>customers.id → orders.customer_id<br>customers.id → user_events.user_id</code></div><p class="muted small-text">示例的关联映射已确认。选择客户后，把其标识分别作为查询参数；不是将多个库直接拼成一条 SQL。</p>${A.notice('修改绑定需要进入草稿编辑，保存前不影响正在使用的工作台。','subtle')}`,`${A.btn('关闭','close-modal')}${A.btn('修改绑定','edit-bindings','','primary','settings')}`,true);
 }
 if(modal==='data-notes')return A.modal('数据说明',`<div class="notice subtle">${A.icon('info',18)}<div>当前所有 SQL 与结果均为示例，不会连接数据库或执行 SQL。</div></div><dl class="detail-fields"><div><dt>工作台</dt><dd>${A.e(ws.title)}</dd></div><div><dt>来源范围</dt><dd>${ws.datasourceIds.length} 个连接，各自执行查询</dd></div><div><dt>统计口径</dt><dd>订单指标统计全部匹配记录，不仅当前分页；客户与使用模块有独立口径。</dd></div><div><dt>权限</dt><dd>${A.currentPolicy()?A.currentPolicy().description:'开源版单用户模拟；当前无团队策略限制'}</dd></div></dl>${Object.entries(ws.bindings).map(([k,id])=>`<div class="sql-block"><div>${A.bindingLabel[k]} <span>${A.e(A.source(id)?.name||'未绑定')}</span></div><pre>${A.e(k==='orders'?'SELECT permitted_columns FROM orders\nWHERE (:customer_id IS NULL OR customer_id = :customer_id)\n  AND /* trusted row-scope predicate */ TRUE\nORDER BY created_at DESC LIMIT :limit;':k==='profile'?'SELECT permitted_columns FROM customers\nWHERE /* trusted row-scope predicate */ TRUE;':'SELECT date_bucket, COUNT(*) FROM user_events\nWHERE user_id = :customer_id\nGROUP BY date_bucket;')}</pre></div>`).join('')}<p class="small-note">SQL 中的权限占位只表达设计意图，不是可以直接使用的安全策略实现。</p>`,A.btn('知道了','close-modal','','primary'),true,true);
 if(modal==='order-detail'){
  const q=A.queryOrders(ws,A.ui),row=q.rows.find(r=>r.id===A.ui.orderId),p=A.currentPolicy();if(!row)return A.modal('订单详情',A.empty('记录不可访问','数据源、记录权限或当前筛选已变化。','lock'),A.btn('关闭','close-modal'));
  const fields=[['订单编号',row.id],['客户',row.customer],['实付金额',A.money(row.amount)],...((!p||p.fields.cost!=='hidden')&&ws.config.showCost?[['订单成本',p?.fields.cost==='masked'?'••••':A.money(row.cost)]]:[]),['状态',row.status],['支付渠道',row.channel],...((!p||p.fields.phone!=='hidden')&&ws.config.showPhone&&row.phone!==undefined?[['手机号',row.phone]]:[]),...(row.email!==undefined?[['邮箱',row.email]]:[]),['门店',row.store],['创建时间',A.date(row.createdAt)]];
  return A.modal('订单详情',`<div class="detail-record-title"><span class="workspace-icon">${A.icon('table',22)}</span><div><strong>${row.id}</strong><p>${row.product}</p></div>${A.badge(row.status,'warning')}</div><dl class="detail-fields">${fields.map(([l,v])=>`<div><dt>${l}${p?.fields.phone==='masked'&&l==='手机号'?A.badge('脱敏','warning'):''}</dt><dd>${A.e(v)}</dd></div>`).join('')}</dl>${p?A.notice(`当前按「${p.label}」演示策略返回字段；隐藏字段不在此详情中展示。`,'subtle','shield'):A.notice('只读预览，不提供退款或修改业务状态的操作。','subtle','lock')}`,`${A.btn('关闭','close-modal')}${A.btn('复制订单号','copy-order','','primary','copy')}`,false,true);
 }
 if(modal==='rename-workspace')return A.modal('重命名工作台',A.field('名称',A.input('renameTitle',A.ui.renameTitle,'工作台名称','maxlength="60"')),`${A.btn('取消','close-modal')}${A.btn('保存名称','confirm-rename',!(A.ui.renameTitle||'').trim()?'disabled':'','primary')}`);
 if(modal==='confirm')return A.modal(A.ui.confirmTitle,`<p class="confirm-description">${A.e(A.ui.confirmText)}</p>`,`${A.btn('取消','close-modal')}${A.btn(A.ui.confirmLabel||'确认','confirm-action','','danger')}`);
 return '';
};

/* Native DOM design renderer. Independent of the React19 / Vite8 implementation. */
A.toast=(text,kind='success')=>{const root=document.querySelector('#toast-root');if(!root)return;const el=document.createElement('div');el.className='toast '+kind;el.setAttribute('role','status');el.innerHTML=A.icon(kind==='error'?'warning':'check',16)+`<span>${A.e(text)}</span>`;root.append(el);setTimeout(()=>el.remove(),4200);};
A.render=()=>{const active=document.activeElement,focusId=active?.id,selection=active&&'selectionStart'in active?[active.selectionStart,active.selectionEnd]:null;const windowY=window.scrollY;document.querySelector('#app').innerHTML=A.shell((A.pages[A.ui.route]||A.pages.home)());const d=document.querySelector('#active-modal');if(d&&!d.open)d.showModal();if(focusId){const target=document.getElementById(focusId);if(target){target.focus({preventScroll:true});if(selection&&target.setSelectionRange)try{target.setSelectionRange(...selection);}catch{}}}window.scrollTo(0,windowY);};
A.activeWs=()=>A.ui.route==='editor'?A.ui.draft:A.workspace();
A.cancelGeneration=()=>{A.ui.generationToken=(A.ui.generationToken||0)+1;A.ui.generating=false;};
A.closeModal=()=>{A.ui.modal=null;A.ui.sourceForm=null;A.ui.testResult=null;A.ui.testing=false;A.ui.testToken=(A.ui.testToken||0)+1;A.render();if(A.ui.returnFocusId)document.getElementById(A.ui.returnFocusId)?.focus();};
A.openModal=(name)=>{A.ui.returnFocusId=document.activeElement?.id;A.ui.modal=name;A.render();};
A.confirm=(title,text,fn,label='确认')=>{A.ui.confirmTitle=title;A.ui.confirmText=text;A.ui.confirmFn=fn;A.ui.confirmLabel=label;A.openModal('confirm');};
A.navigate=(route,id,force=false)=>{
 if(A.ui.route==='editor'&&A.ui.editorDirty&&route!=='editor'&&!force){A.confirm('离开未保存的草稿？','当前草稿保留在这个浏览器；已保存的工作台不会被修改。',()=>{if(A.ui.editorOriginal){A.state.drafts[A.ui.editorOriginal.id]=structuredClone(A.ui.draft);A.save();}A.ui.editorDirty=false;A.navigate(route,id,true);},'保留草稿并离开');return;}
 if(A.ui.route==='permissions'&&A.ui.policyDirty&&route!=='permissions'&&!force){A.confirm('放弃策略修改？','尚未保存的数据权限修改不会生效。',()=>{A.ui.policyDraft=null;A.ui.policyDirty=false;A.navigate(route,id,true);},'放弃并离开');return;}
 if(A.ui.route==='editor'&&route!=='editor')A.cancelGeneration();A.ui.modal=null;A.ui.navOpen=false;A.ui.route=route;if(id)A.ui.workspaceId=id;const next='#/'+route+(id?'/'+encodeURIComponent(id):'');if(location.hash!==next)history.pushState(null,'',next);A.ui.lastRoute=location.hash;A.render();window.scrollTo(0,0);
};
A.changeDirty=()=>{A.ui.editorDirty=true;if(A.ui.editorOriginal){A.state.drafts[A.ui.editorOriginal.id]=structuredClone(A.ui.draft);A.save();}};
A.ensurePolicyDraft=()=>{if(!A.ui.policyDraft)A.ui.policyDraft=structuredClone(A.state.policies[A.ui.permissionRole]);return A.ui.policyDraft;};
A.actions={
 'nav':el=>A.navigate(el.dataset.page),
 'toggle-nav':()=>{A.ui.navOpen=!A.ui.navOpen;A.render();},
 'close-modal':()=>A.closeModal(),
 'confirm-action':()=>{const fn=A.ui.confirmFn;A.ui.modal=null;A.ui.confirmFn=null;if(fn)fn();},
 'open-workspace':el=>{const id=el.dataset.id;if(!A.state.workspaces.some(w=>w.id===id)){A.toast('示例工作台已删除，请从目录选择或重置演示数据','error');return;}A.ui.search='';A.ui.channel='all';A.ui.customer='all';A.ui.page=1;A.ui.days=A.state.workspaces.find(w=>w.id===id).config.defaultDays||'30';A.navigate('workspace',id);},
 'create-workspace':()=>{const create=()=>{A.ui.modal=null;A.startEditor(undefined,'创建一个客户业务总览工作台','customer',A.ui.createSources);};if(A.ui.route==='editor'&&A.ui.editorDirty)A.confirm('新建另一个工作台？','当前未保存的创建草稿会被替换；已保存工作台的修改草稿仍保留在本地。',create,'新建工作台');else create();},
 'generate-home':()=>{const prompt=(A.ui.homePrompt||'').trim();if(!prompt){A.toast('先描述需求，或点击下方示例任务','error');return;}const kind=prompt.includes('订单')&&!prompt.includes('客户')&&!prompt.includes('会员')?'orders':prompt.includes('检索')?'members':'customer';A.startEditor(undefined,prompt,kind,A.ui.createSources);},
 'template':el=>{const kind=el.dataset.template;A.startEditor(undefined,kind==='customer'?'做一个客户总览，组合会员资料、订单和使用情况。':kind==='orders'?'做一个异常订单排查工作台。':'做一个高价值客户检索工作台。',kind,kind==='customer'?['orders','members','events']:kind==='orders'?['orders']:['members']);},
 'edit-workspace':()=>{if(A.currentPolicy()){A.toast('当前处于普通成员预览，不能修改工作台','error');return;}A.startEditor(A.workspace()?.id);},
 'leave-editor':()=>A.navigate(A.ui.editorOriginal?'workspace':'workspaces',A.ui.editorOriginal?.id),
 'discard-editor':()=>A.confirm('放弃当前修改？','恢复已保存的工作台，不会修改任何数据库记录。',()=>{A.cancelGeneration();if(A.ui.editorOriginal){delete A.state.drafts[A.ui.editorOriginal.id];A.save();}const orig=A.ui.editorOriginal;A.ui.editorDirty=false;A.ui.draft=null;A.navigate(orig?'workspace':'workspaces',orig?.id,true);},'放弃修改'),
 'save-workspace':()=>{const ws=A.ui.draft;if(A.currentPolicy()){A.toast('普通成员预览不能保存工作台修改','error');return;}const required=ws.kind==='customer'?['orders','profile',...(ws.config.showActivity?['activity']:[])]:ws.kind==='orders'?['orders']:['profile'];if(required.some(k=>!ws.bindings[k]||!A.validBinding(k,ws.bindings[k]))){A.ui.editorTab='data';A.render();A.toast('请先为所有显示中的模块绑定兼容数据源','error');return;}const w=A.normalizeWorkspace(ws);if(!w.title.trim()){A.toast('工作台名称不能为空','error');return;}const original=A.ui.editorOriginal;w.version=(original?.version||0)+1;w.updated=new Date().toISOString();if(original)w.previousDefinition={bindings:original.bindings,datasourceIds:original.datasourceIds,config:original.config};A.state.workspaces=original?A.state.workspaces.map(x=>x.id===w.id?w:x):[w,...A.state.workspaces];delete A.state.drafts[w.id];A.save();A.ui.editorDirty=false;A.ui.draft=null;A.navigate('workspace',w.id,true);A.toast('工作台已保存到当前浏览器');},
 'editor-tab':el=>{A.ui.editorTab=el.dataset.tab;A.render();},
 'mobile-editor':el=>{A.ui.mobileEditor=el.dataset.tab;A.render();},
 'editor-suggest':el=>{A.ui.editorPrompt=el.dataset.prompt;A.render();document.getElementById('editorPrompt')?.focus();},
 'send-editor':()=>{const text=(A.ui.editorPrompt||'').trim();if(!text||A.ui.generating)return;A.ui.editorPrompt='';A.ui.messages.push({role:'user',text});if(A.currentPolicy()){A.ui.messages.push({role:'assistant',text:'当前成员预览没有编辑权限；AI 也不能改变数据策略。'});A.render();return;}A.ui.generating=true;const token=(A.ui.generationToken||0)+1;A.ui.generationToken=token;A.render();setTimeout(()=>{if(token!==A.ui.generationToken||A.ui.route!=='editor')return;const d=A.ui.draft;let changes=[];if(/隐藏|移除|去掉/.test(text)&&/手机/.test(text)){d.config.showPhone=false;changes.push('在布局中隐藏手机号，不改变底层数据权限');}else if(/手机/.test(text)){d.config.showPhone=true;changes.push('显示已授权的手机号；成员脱敏规则仍然生效');}if(/成本/.test(text)){d.config.showCost=!/隐藏|移除|去掉/.test(text);changes.push(d.config.showCost?'显示有权读取的订单成本':'隐藏成本列');}if(/趋势|行为/.test(text)){if(/隐藏|移除|去掉/.test(text)){d.config.showActivity=false;changes.push('隐藏使用趋势模块');}else if(d.kind!=='customer'){changes.push('此演示只在客户总览模板支持使用趋势，当前模板未修改');}else {d.config.showActivity=true;if(!d.bindings.activity){const id=d.datasourceIds.find(id=>A.source(id)?.domain==='events');d.bindings.activity=id||'';}changes.push(d.bindings.activity?'增加使用趋势；沿用已确认的客户标识映射':'已添加趋势占位，请在数据与模块中绑定行为数据源');}}A.ui.generating=false;A.ui.messages.push({role:'assistant',text:changes.length?'草稿预览已更新，请核对后保存。':'这个请求超出当前 Mock 范围。可以试试“隐藏手机号”“显示成本”或“增加使用趋势”，也可直接调整模块绑定。',changes:changes.length?changes:undefined});if(changes.length)A.changeDirty();A.render();},1100);},
 'stop-generation':()=>{A.cancelGeneration();A.ui.messages.push({role:'assistant',text:'已停止模拟生成，未应用这次请求。'});A.render();},
 'select-create-sources':()=>{A.ui.pickerContext='home';A.ui.pickerIds=[...(A.ui.createSources||['orders','members','events'])];A.openModal('source-picker');},
 'choose-editor-sources':()=>{A.ui.pickerContext='editor';A.ui.pickerIds=[...A.ui.draft.datasourceIds];A.openModal('source-picker');},
 'apply-source-picker':()=>{if(A.ui.pickerContext==='editor'){A.ui.draft.datasourceIds=[...A.ui.pickerIds];for(const [key,id]of Object.entries(A.ui.draft.bindings))if(id&&!A.ui.pickerIds.includes(id))A.ui.draft.bindings[key]='';A.changeDirty();A.ui.editorTab='data';}else A.ui.createSources=[...A.ui.pickerIds];A.ui.modal=null;A.render();A.toast('数据源范围已更新');},
 'bindings':()=>A.openModal('bindings'),
 'module-source':el=>{A.ui.moduleKey=el.dataset.module;A.openModal('module-source');},
 'edit-bindings':()=>{A.ui.modal=null;if(A.currentPolicy()){A.render();A.toast('当前成员预览不能修改数据源绑定','error');return;}if(A.ui.route!=='editor')A.startEditor(A.workspace().id);A.ui.editorTab='data';A.render();},
 'data-notes':()=>A.openModal('data-notes'),
 'select-customer':el=>{A.ui.customer=el.dataset.id;A.ui.page=1;A.render();},
 'clear-customer':()=>{A.ui.customer='all';A.ui.page=1;A.render();},
 'reset-filters':()=>{A.ui.customer='all';A.ui.search='';A.ui.channel='all';A.ui.days='30';A.ui.page=1;A.render();},
 'page-prev':()=>{A.ui.page=Math.max(1,A.ui.page-1);A.render();},
 'page-next':()=>{A.ui.page++;A.render();},
 'order-detail':el=>{A.ui.orderId=el.dataset.id;A.openModal('order-detail');},
 'copy-order':async()=>{try{await navigator.clipboard.writeText(A.ui.orderId);A.toast('订单号已复制');}catch{A.toast('浏览器未授予复制权限，请选中订单号复制','error');}},
 'refresh-workspace':()=>{A.ui.refreshing=true;A.render();A.toast('正在分别读取绑定的数据源…','info');setTimeout(()=>{A.ui.refreshing=false;const ws=A.activeWs();if(!ws)return;const unavailable=ws.datasourceIds.filter(id=>!A.sourceAccess(id).ok).length;A.render();A.toast(unavailable?`模拟刷新完成，${unavailable} 个来源不可用；其他模块已更新`:'所有授权模块已完成模拟刷新',unavailable?'info':'success');},550);},
 'export-orders':()=>{const ws=A.activeWs();const q=A.queryOrders(ws,A.ui),p=A.currentPolicy();if(!A.canExport()||!q.ok){A.toast('当前角色或来源不允许导出','error');return;}const cols=[['id','订单编号'],['customer','客户'],['amount','实付金额'],['channel','支付渠道'],['status','状态'],['store','门店'],...(ws.config.showPhone&&(!p||p.fields.phone!=='hidden')?[['phone','手机号']]:[]),...(!p||p.fields.email!=='hidden'?[['email','邮箱']]:[]),...(ws.config.showCost&&(!p||p.fields.cost!=='hidden')?[['cost','成本']]:[])];const safe=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff'+[cols.map(c=>safe(c[1])).join(','),...q.rows.map(r=>cols.map(([k])=>safe(r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='stackoryn-orders-mock.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);A.toast(`已导出 ${q.rows.length} 条授权范围内的模拟记录`);},
 'source-detail':el=>{A.ui.sourceId=el.dataset.id;A.ui.sourceTab=el.dataset.tab||'overview';A.openModal('source-detail');},
 'source-tab':el=>{A.ui.sourceTab=el.dataset.tab;A.render();},
 'filter-engine':el=>{A.ui.engineFilter=el.dataset.value;A.render();},
 'add-source':()=>A.startSourceForm(),
 'edit-source':el=>A.startSourceForm(el.dataset.id),
 'select-engine':el=>{const engine=el.dataset.engine;const f=A.ui.sourceForm;f.engine=engine;f.port=engine==='PostgreSQL'?'5432':engine==='MySQL'?'3306':'8443';f.domain=engine==='PostgreSQL'?'orders':engine==='MySQL'?'members':'events';f.tables={orders:['orders','payments'],members:['customers','subscriptions'],events:['user_events']}[f.domain];A.ui.testResult=null;A.render();},
 'source-step-next':()=>{if(A.ui.sourceStep===1)A.ui.sourceStep=2;else if(A.ui.testResult==='success')A.ui.sourceStep=3;A.render();},
 'source-step-back':()=>{A.ui.sourceStep=Math.max(1,A.ui.sourceStep-1);A.render();},
 'test-source':()=>{const f=A.ui.sourceForm;if(!f.name.trim()||!f.host.trim()||!f.database.trim()||!f.username.trim()||!Number.isInteger(Number(f.port))||Number(f.port)<1||Number(f.port)>65535){A.ui.formError='请填写名称、主机、数据库、模拟账号和有效端口。';A.render();return;}A.ui.formError='';A.ui.testing=true;A.ui.testResult=null;const token=(A.ui.testToken||0)+1;A.ui.testToken=token;A.render();setTimeout(()=>{if(token!==A.ui.testToken||A.ui.modal!=='source-form')return;A.ui.testing=false;A.ui.testResult=f.fail||f.host.includes('fail')?'error':'success';A.render();},650);},
 'save-source':()=>{const f=A.ui.sourceForm;if(A.ui.testResult!=='success'||!f.tables.length)return;const id=A.ui.editSourceId||A.uid('ds');const ds={id,name:f.name.trim(),host:f.host.trim(),port:f.port,database:f.database.trim(),engine:f.engine,environment:f.environment,state:'connected',tables:[...f.tables],domain:f.domain,ssl:f.ssl,updated:'刚刚'};const refs=A.state.workspaces.some(w=>Object.entries(w.bindings).some(([key,sid])=>sid===id&&A.bindingDomain[key]!==f.domain));if(refs){A.toast('此来源已被模块引用，不能直接变更其示例业务结构','error');return;}if(A.ui.editSourceId)A.state.sources=A.state.sources.map(s=>s.id===id?ds:s);else A.state.sources.push(ds);A.save();A.ui.sourceForm=null;A.ui.modal=null;A.ui.testResult=null;A.render();A.toast('已保存模拟数据源，未保存密码或建立真实连接');},
 'toggle-source':el=>{const s=A.source(el.dataset.id);if(!s)return;s.state=s.state==='connected'?'offline':'connected';s.updated='刚刚';A.save();A.render();A.toast(s.state==='offline'?'已模拟断开此来源；其他来源不受影响':'模拟连接已恢复');},
 'restore-source':el=>{const s=A.source(el.dataset.id);if(!s)return;s.state='connected';s.updated='刚刚';A.save();A.render();A.toast('模拟连接已恢复');},
 'delete-source':el=>{const id=el.dataset.id;if(A.state.workspaces.some(w=>w.datasourceIds.includes(id))){A.toast('请先解除所有工作台引用','error');return;}A.confirm('删除这个数据源？','仅删除当前浏览器里的连接配置，不会删除数据库。',()=>{A.state.sources=A.state.sources.filter(s=>s.id!==id);A.save();A.ui.modal=null;A.render();A.toast('模拟数据源已删除');},'删除连接');},
 'rename-workspace':el=>{A.ui.renameId=el.dataset.id;A.ui.renameTitle=A.state.workspaces.find(w=>w.id===el.dataset.id)?.title||'';A.openModal('rename-workspace');},
 'confirm-rename':()=>{const title=(A.ui.renameTitle||'').trim();if(!title)return;const w=A.state.workspaces.find(w=>w.id===A.ui.renameId);w.title=title;w.updated=new Date().toISOString();A.save();A.ui.modal=null;A.render();A.toast('名称已更新');},
 'copy-workspace':el=>{const orig=A.state.workspaces.find(w=>w.id===el.dataset.id);const w=structuredClone(orig);w.id=A.uid('workspace');w.title+=' · 副本';w.version=1;w.updated=new Date().toISOString();A.state.workspaces.unshift(w);A.save();A.render();A.toast('已创建独立副本，不会复制额外数据权限');},
 'delete-workspace':el=>{const id=el.dataset.id;A.confirm('删除工作台？','仅删除这个模拟界面与草稿，不会删除数据源或数据库记录。',()=>{A.state.workspaces=A.state.workspaces.filter(w=>w.id!==id);delete A.state.drafts[id];A.save();A.ui.modal=null;A.render();A.toast('工作台已删除');},'删除工作台');},
 'enter-team':()=>{A.state.edition='team';A.ui.role='owner';A.save();A.navigate('permissions');},
 'set-edition':el=>{A.state.edition=el.dataset.edition;A.ui.role='owner';A.ui.policyDraft=null;A.ui.policyDirty=false;A.save();A.render();A.toast(A.state.edition==='community'?'已回到单用户开源版原型':'已进入团队版设计预览，云端连接方案仍待定');},
 'permission-role':el=>{const apply=()=>{A.ui.permissionRole=el.dataset.role;A.ui.policyDraft=null;A.ui.policyDirty=false;A.ui.modal=null;A.render();};if(A.ui.policyDirty)A.confirm('切换角色并放弃未保存修改？','当前策略修改尚未生效。',apply,'放弃并切换');else apply();},
 'policy-tab':el=>{A.ui.scopeTab=el.dataset.tab;A.render();},
 'save-policy':()=>{if(!A.ui.policyDraft)return;A.state.policies[A.ui.permissionRole]=structuredClone(A.ui.policyDraft);A.ui.policyDraft=null;A.ui.policyDirty=false;A.save();A.render();A.toast('模拟策略已保存；不是服务端授权');},
 'policy-preview':()=>{if(A.ui.policyDirty)return;A.ui.role=A.ui.permissionRole;A.ui.customer='all';A.ui.page=1;A.ui.search='';A.ui.channel='all';A.navigate('workspace',A.state.workspaces.some(w=>w.id==='customer-360')?'customer-360':A.state.workspaces[0]?.id);},
 'reset-demo':()=>A.confirm('重置这版演示数据？','会清除 v0.2 原型创建的工作台、数据源和策略，不影响旧版演示或真实数据库。',()=>{A.state=A.initial();A.ui={};A.ensureUI();A.save();A.navigate('home',undefined,true);A.toast('演示数据已重置');},'确认重置')
};
A.startSourceForm=id=>{const source=A.source(id);A.ui.editSourceId=id||null;A.ui.sourceStep=source?2:1;A.ui.testResult=null;A.ui.testing=false;A.ui.formError='';A.ui.sourceForm=source?{...structuredClone(source),username:'demo_readonly',password:'',fail:false}:{name:'',engine:'PostgreSQL',environment:'生产',host:'',port:'5432',database:'',username:'demo_readonly',password:'',ssl:true,domain:'orders',tables:['orders','payments'],fail:false};A.openModal('source-form');};
A.handleInput=(el)=>{const id=el.dataset.model;if(!id)return;const value=el.type==='checkbox'?el.checked:el.value;
 const simple={homePrompt:'homePrompt',editorPrompt:'editorPrompt',orderSearch:'search',orderChannel:'channel',orderDays:'days',orderSort:'sort',workspaceCustomer:'customer',sourceSearch:'sourceSearch',workspaceSearch:'workspaceSearch',workspaceSource:'workspaceSource',renameTitle:'renameTitle'};
 if(id in simple){A.ui[simple[id]]=value;if(['orderSearch','orderChannel','orderDays','workspaceCustomer'].includes(id))A.ui.page=1;if(['homePrompt','editorPrompt'].includes(id))return;}
 else if(id==='previewRole'){A.ui.role=value;A.ui.customer='all';A.ui.page=1;A.ui.modal=null;}
 else if(id.startsWith('ds-table-')){const key=id.slice(9),f=A.ui.sourceForm;f.tables=value?[...new Set([...f.tables,key])]:f.tables.filter(t=>t!==key);}
 else if(id.startsWith('ds-')){const key=id.slice(3);A.ui.sourceForm[key]=value;A.ui.testResult=null;A.ui.testing=false;A.ui.testToken=(A.ui.testToken||0)+1;if(key==='domain')A.ui.sourceForm.tables={orders:['orders','payments'],members:['customers','subscriptions'],events:['user_events']}[value];if(key==='password')return;}
 else if(id.startsWith('pick-')){const sid=id.slice(5);A.ui.pickerIds=value?[...new Set([...A.ui.pickerIds,sid])]:A.ui.pickerIds.filter(x=>x!==sid);}
 else if(id.startsWith('binding-')){const key=id.slice(8);if(!A.validBinding(key,value))return;A.ui.draft.bindings[key]=value;A.changeDirty();}
 else if(id.startsWith('config-')){A.ui.draft.config[id.slice(7)]=value;A.changeDirty();}
 else if(id.startsWith('policy-field-')){A.ensurePolicyDraft().fields[id.slice(13)]=value;A.ui.policyDirty=true;}
 else if(id==='policy-rowScope'){A.ensurePolicyDraft().rowScope=value;A.ui.policyDirty=true;}
 else if(id==='policy-export'||id==='policy-aiSensitive'){A.ensurePolicyDraft()[id.slice(7)]=value;A.ui.policyDirty=true;}
 else if(id.startsWith('policy-source-')){const p=A.ensurePolicyDraft(),sid=id.slice(14);p.allowedSources=value?[...new Set([...p.allowedSources,sid])]:p.allowedSources.filter(x=>x!==sid);A.ui.policyDirty=true;}
 A.render();
};
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target&&!target.disabled){const action=A.actions[target.dataset.action];if(action)action(target,event);}else if(event.target===document.querySelector('#active-modal'))A.closeModal();});
document.addEventListener('input',event=>{if(event.target.matches('input:not([type="checkbox"]):not([type="radio"]),textarea'))A.handleInput(event.target);});
document.addEventListener('change',event=>{if(event.target.matches('select,input[type="checkbox"],input[type="radio"]'))A.handleInput(event.target);});
document.addEventListener('cancel',event=>{if(event.target.id==='active-modal'){event.preventDefault();A.closeModal();}},true);
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('tr[data-action]'))A.actions[event.target.dataset.action](event.target);if((event.ctrlKey||event.metaKey)&&event.key==='Enter'&&event.target.id==='editorPrompt')A.actions['send-editor']();});
window.addEventListener('beforeunload',event=>{if(A.ui.editorDirty||A.ui.policyDirty){event.preventDefault();event.returnValue='';}});
A.readRoute=()=>{const [page,id]=location.hash.replace(/^#\/?/,'').split('/');const defaultPage=document.documentElement.dataset.page||'workspace';A.ui.route=page||defaultPage;if(id)A.ui.workspaceId=decodeURIComponent(id);if(A.ui.route==='editor'&&!A.ui.draft){A.startEditor(A.ui.workspaceId);return;}A.ui.lastRoute=location.hash;A.render();};
window.addEventListener('popstate',()=>{const desired=location.hash;if((A.ui.editorDirty||A.ui.policyDirty)&&A.ui.lastRoute!==desired){history.pushState(null,'',A.ui.lastRoute);const [page,id]=desired.replace(/^#\/?/,'').split('/');A.navigate(page||'home',id);return;}A.readRoute();});
A.readRoute();

})();